let cleanup=null;function showTopBar(){let e=document.querySelector(".top-gradient-bar");e&&(e.classList.remove("visible"),e.offsetHeight,setTimeout(()=>{e.classList.add("visible")},2e3))}function showTopBarModal(){let e=document.querySelector(".top-gradient-bar_modal");e&&(e.classList.remove("visible"),e.offsetHeight,setTimeout(()=>{e.classList.add("visible")},2e3))}function showTopBarProduct(){let e=document.querySelector(".top-gradient-bar_products");e&&(e.classList.remove("visible"),e.offsetHeight,setTimeout(()=>{e.classList.add("visible")},2e3))}function startWelcomeSlider(){console.log("startWelcomeSlider ejecutado");let e=document.querySelectorAll(".about-slider picture");if(!e.length)return;let t=0;e.forEach(e=>e.classList.remove("active")),e[0].classList.add("active");let a=setInterval(()=>{e[t].classList.remove("active"),e[t=(t+1)%e.length].classList.add("active")},4e3);cleanup=()=>clearInterval(a)}const openBtn=document.getElementById("ws-modal"),modal=document.getElementById("modal-container"),closeBtn=document.getElementById("close-modal");function startPromotionSlider(){let e=document.querySelectorAll(".promotion-slider picture");if(!e.length)return;let t=0;e.forEach(e=>e.classList.remove("active")),e[0].classList.add("active");let a=setInterval(()=>{e[t].classList.remove("active"),e[t=(t+1)%e.length].classList.add("active")},4e3);cleanup=()=>clearInterval(a)}function initHome(){console.log("initHome ejecutado"),"function"==typeof cleanup&&cleanup();let e=document.getElementById("miVideo");e.playbackRate=.4,showTopBar(),showTopBarProduct(),startWelcomeSlider(),startPromotionSlider()}openBtn.addEventListener("click",e=>{e.preventDefault(),modal.style.display="flex"}),closeBtn.addEventListener("click",()=>{modal.style.display="none"}),initHome();const navToggle=document.getElementById("navToggle"),navOverlay=document.getElementById("navOverlay"),navSidebar=document.getElementById("navSidebar");function openSidebar(){navOverlay.classList.add("active"),navSidebar.classList.add("active")}function closeSidebar(){navOverlay.classList.remove("active"),navSidebar.classList.remove("active")}navToggle.addEventListener("click",openSidebar),navOverlay.addEventListener("click",closeSidebar);const closeModalBtn=document.getElementById("closeModalBtn");closeModalBtn.addEventListener("click",()=>{!1===modalIsOpen?history.back():closeModal()});
